-- ----------------------------------------------------------------------------
-- Graphs: The explainer page as one graph: its wording variables and its totals.
-- ----------------------------------------------------------------------------
CREATE TABLE graphs (
  graph_id                            TEXT                 PRIMARY KEY,         -- Key of the graph.
  label                               TEXT                ,                     -- Display name of the graph.
  literal_quote                       TEXT                ,                     -- The quote mark written around a literal value in a fact's wording.
  literal_type_marker                 TEXT                ,                     -- The marker written between a literal value and its datatype, as in Turtle.
  built_in_source_text                TEXT                ,                     -- Source line shown for a fact the page states as a teaching example.
  user_source_text                    TEXT                ,                     -- Source line shown for a fact the reader stated.
  no_conclusions_text                 TEXT                                      -- Message shown when the selected facts and rules add no conclusion.
);
COMMENT ON TABLE graphs IS 'The explainer page as one graph: its wording variables and its totals.';
COMMENT ON COLUMN graphs.graph_id IS 'Key of the graph.';
COMMENT ON COLUMN graphs.label IS 'Display name of the graph.';
COMMENT ON COLUMN graphs.literal_quote IS 'The quote mark written around a literal value in a fact''s wording.';
COMMENT ON COLUMN graphs.literal_type_marker IS 'The marker written between a literal value and its datatype, as in Turtle.';
COMMENT ON COLUMN graphs.built_in_source_text IS 'Source line shown for a fact the page states as a teaching example.';
COMMENT ON COLUMN graphs.user_source_text IS 'Source line shown for a fact the reader stated.';
COMMENT ON COLUMN graphs.no_conclusions_text IS 'Message shown when the selected facts and rules add no conclusion.';

-- ----------------------------------------------------------------------------
-- Rules: The five rule switches on the page.
-- ----------------------------------------------------------------------------
CREATE TABLE rules (
  rule_id                             TEXT                 PRIMARY KEY,         -- Key of the rule.
  label                               TEXT                ,                     -- The rule's name on the page.
  explanation                         TEXT                ,                     -- The rule's one-line explanation on the page.
  is_enabled                          BOOLEAN             ,                     -- The rule's checkbox.
  sort_order                          INTEGER                                   -- Position in the rule list.
);
COMMENT ON TABLE rules IS 'The five rule switches on the page.';
COMMENT ON COLUMN rules.rule_id IS 'Key of the rule.';
COMMENT ON COLUMN rules.label IS 'The rule''s name on the page.';
COMMENT ON COLUMN rules.explanation IS 'The rule''s one-line explanation on the page.';
COMMENT ON COLUMN rules.is_enabled IS 'The rule''s checkbox.';
COMMENT ON COLUMN rules.sort_order IS 'Position in the rule list.';

-- ----------------------------------------------------------------------------
-- FiringKinds: The ways a rule can apply. Domain and range belong to one rule but are worded apart.
-- ----------------------------------------------------------------------------
CREATE TABLE firing_kinds (
  firing_kind_id                      TEXT                 PRIMARY KEY,         -- Key of the kind.
  rule                                TEXT                ,                     -- The rule switch this kind belongs to.
  wording                             TEXT                ,                     -- How a conclusion card names the rule, as in 'Worked out by the inverse rule'.
  sort_order                          INTEGER                                   -- Order in which the page's reasoner tries the kinds for one fact.
);
COMMENT ON TABLE firing_kinds IS 'The ways a rule can apply. Domain and range belong to one rule but are worded apart.';
COMMENT ON COLUMN firing_kinds.firing_kind_id IS 'Key of the kind.';
COMMENT ON COLUMN firing_kinds.rule IS 'The rule switch this kind belongs to.';
COMMENT ON COLUMN firing_kinds.wording IS 'How a conclusion card names the rule, as in ''Worked out by the inverse rule''.';
COMMENT ON COLUMN firing_kinds.sort_order IS 'Order in which the page''s reasoner tries the kinds for one fact.';

-- ----------------------------------------------------------------------------
